        lines = f.read().splitlines()
    max_len = max(len(l) for l in lines)
    grid = [list(l.ljust(max_len)) for l in lines]
    return grid

grid = read_grid('/app/dataset/genealogy_trees.txt')
R = len(grid)
C = len(grid[0])

# 1. Parse boxes (same as before)
raw_names = []
for r in range(R):
    line = "".join(grid[r])
    for match in re.finditer(r'[A-Za-ząćęłńóśźżĄĆĘŁŃÓŚŹŻ]+(?: [A-Za-ząćęłńóśźżĄĆĘŁŃÓŚŹŻ]+)*', line):
        name = match.group(0)
        if len(name) < 2 or name == "FAMILY TREE GENERATOR" or name == "FAMILY":
            continue
        raw_names.append({
            'text': name, 'r': r,
            'c_start': match.start(), 'c_end': match.end()
        })

boxes = []
used = set()
for i, n1 in enumerate(raw_names):
    if i in used: continue
    current_box = [n1]
    used.add(i)
    while True:
        last_n = current_box[-1]
        found_next = False
        for j, n2 in enumerate(raw_names):
            if j not in used and n2['r'] == last_n['r'] + 1:
                if not (n2['c_end'] < last_n['c_start'] - 2 or n2['c_start'] > last_n['c_end'] + 2):
                    current_box.append(n2)
                    used.add(j)
                    found_next = True
                    break
        if not found_next: break

    full_name = " ".join(part['text'] for part in current_box)
    min_r = current_box[0]['r']
    max_r = current_box[-1]['r']
    min_c = min(part['c_start'] for part in current_box)
    max_c = max(part['c_end'] for part in current_box)

    left_border = min_c
    for c in range(min_c, max(0, min_c - 10), -1):
        if grid[min_r][c] in '|│+': left_border = c; break
    right_border = max_c
    for c in range(max_c, min(C, max_c + 10)):
        if grid[min_r][c] in '|│+': right_border = c; break
    top_border = min_r
    for r in range(min_r, max(0, min_r - 5), -1):
        if '-' in grid[r][left_border:right_border+1] or '~' in grid[r][left_border:right_border+1] or '+' in grid[r][left_border:right_border+1]:
            top_border = r; break
    bottom_border = max_r
    for r in range(max_r, min(R, max_r + 5)):
        if '-' in grid[r][left_border:right_border+1] or '~' in grid[r][left_border:right_border+1] or '+' in grid[r][left_border:right_border+1]:
            bottom_border = r; break

    boxes.append({
        'name': full_name,
        'top_r': top_border, 'bottom_r': bottom_border,
        'left_c': left_border, 'right_c': right_border
    })

# Map each grid cell to a box index if it's inside or on the border of a box
cell_to_box = {}
for i, b in enumerate(boxes):
    for r in range(b['top_r'], b['bottom_r'] + 1):
        for c in range(b['left_c'], b['right_c'] + 1):
            cell_to_box[(r, c)] = i

# 2. Build DAG
# Allowed line characters
LINE_CHARS = set('+-|/\\~')

edges = {} # node -> list of neighbors
def add_edge(u, v):
    if u not in edges: edges[u] = []
    edges[u].append(v)

for r in range(R):
    for c in range(C):
        if grid[r][c] not in LINE_CHARS:
            continue
        # We are at a line character.
        u = (r, c)

        # Horizontal edges (undirected, so we add both ways)
        # Check up to 3 gaps
        for dc in [1, 2, 3]:
            if c + dc < C and grid[r][c+dc] in LINE_CHARS:
                # ensure intermediate chars are spaces
                if all(grid[r][c+k] == ' ' for k in range(1, dc)):
                    v = (r, c+dc)
                    add_edge(u, v)
                    add_edge(v, u)
                    break # only connect to the first found

        # Vertical edges (directed down)
        for dr in [1, 2, 3]:
            if r + dr < R and grid[r+dr][c] in LINE_CHARS:
                if all(grid[r+k][c] == ' ' for k in range(1, dr)):
                    v = (r+dr, c)
                    add_edge(u, v)
                    break

        # Diagonal edges (directed down-right for \, down-left for /)
        if grid[r][c] == '\\':
            for dr in [1, 2]:
                if r + dr < R and c + dr < C and grid[r+dr][c+dr] in LINE_CHARS:
                    add_edge(u, (r+dr, c+dr))
                    break
        elif grid[r][c] == '/':
            for dr in [1, 2]:
                if r + dr < R and c - dr >= 0 and grid[r+dr][c-dr] in LINE_CHARS:
                    add_edge(u, (r+dr, c-dr))
                    break

# 3. Find parent-child relationships
# A box is a child of another if there's a path from Parent's bottom to Child's top.
# For each box, let's find all nodes just below its bottom border that are line chars.
box_bottom_nodes = {i: [] for i in range(len(boxes))}
box_top_nodes = {i: [] for i in range(len(boxes))}

for i, b in enumerate(boxes):
    r_bottom = b['bottom_r']
    # look at row below bottom
    for c in range(b['left_c'], b['right_c'] + 1):
        if r_bottom + 1 < R and grid[r_bottom + 1][c] in LINE_CHARS:
            box_bottom_nodes[i].append((r_bottom + 1, c))
        elif r_bottom + 2 < R and grid[r_bottom + 2][c] in LINE_CHARS and grid[r_bottom + 1][c] == ' ':
            box_bottom_nodes[i].append((r_bottom + 2, c))

    r_top = b['top_r']
    for c in range(b['left_c'], b['right_c'] + 1):
        if r_top - 1 >= 0 and grid[r_top - 1][c] in LINE_CHARS:
            box_top_nodes[i].append((r_top - 1, c))
        elif r_top - 2 >= 0 and grid[r_top - 2][c] in LINE_CHARS and grid[r_top - 1][c] == ' ':
            box_top_nodes[i].append((r_top - 2, c))

# Let's do a BFS from each box's bottom nodes to find all reachable boxes
parents = {} # child_idx -> parent_idx
children = {i: [] for i in range(len(boxes))}

import collections

for parent_idx in range(len(boxes)):
    q = collections.deque(box_bottom_nodes[parent_idx])
    visited = set(q)
    while q:
        curr = q.popleft()

        # Did we reach a box's top?
        # Actually, let's just check if this node is in any box's top nodes
        reached_box = None
        for child_idx, tops in box_top_nodes.items():
            if curr in tops:
                reached_box = child_idx
                break

        if reached_box is not None:
            parents[reached_box] = parent_idx
            children[parent_idx].append(reached_box)
            continue # stop exploring this branch

        # explore neighbors
        if curr in edges:
            for nxt in edges[curr]:
                if nxt not in visited:
                    # check if nxt is inside a box. If so, don't enter it unless it's a top node
                    if nxt not in cell_to_box:
                        visited.add(nxt)
                        q.append(nxt)

print("Parents dict built.")

# Find Dawid Majtyka
dawid_idx = -1
for i, b in enumerate(boxes):
    if "Dawid Majtyka" in b['name']:
        dawid_idx = i
        break

if dawid_idx == -1:
    print("Dawid not found.")
    sys.exit(0)

curr = dawid_idx
for _ in range(4): # up to great-great-grandparent
    if curr in parents:
        curr = parents[curr]
    else:
        print(f"Parent not found for {boxes[curr]['name']}")
        break

gg_parent = boxes[curr]
print(f"Great-great-grandparent: {gg_parent['name']}")

# Now find children of gg_parent with >1 grandchild
gg_children = children[curr]
result_names = []
for c_idx in gg_children:
    c_grandchildren_count = 0
    for gc_idx in children[c_idx]:
        c_grandchildren_count += len(children[gc_idx])
    if c_grandchildren_count > 1:
        result_names.append(boxes[c_idx]['name'])

print(f"Children of GG parent with >1 grandchild: {result_names}")

